<?php
/** NexaBiz SaaS demo ecommerce seeder patch. Safe, file-hash-protected, CLI-only. */
if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only');}
$command=$argv[1]??'--help';
if(!in_array($command,['--dry-run','--apply','--rollback','--help'],true)){fwrite(STDERR,"Unknown command.\n");exit(2);}
$root=__DIR__;
if(!is_file($root.'/artisan')||!is_file($root.'/composer.json')){fwrite(STDERR,"Place this installer beside artisan and composer.json in your Laravel project root.\n");exit(2);}
if(!is_file($root.'/database/migrations/2026_11_24_000002_add_product_subcategory.php')){
 fwrite(STDERR,"The China marketplace V2 patch is required before this demo seeder.\n");exit(2);
}
$backupDir=$root.'/storage/app/nexabiz-patch-backups/ecommerce-demo-seeder-v1';
$stateFile=$backupDir.'/state.json';
function said($s){echo $s,"\n";}
function failPatch($s,$code=1){fwrite(STDERR,$s."\n");exit($code);}
function hashNow($f){return is_file($f)?hash_file('sha256',$f):null;}
function storePatch($file,$data){
 $dir=dirname($file);if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Cannot create '.$dir);
 $tmp=$file.'.nexatmp';if(file_put_contents($tmp,$data,LOCK_EX)===false)throw new RuntimeException('Write failed: '.$tmp);
 if(!rename($tmp,$file)){@unlink($tmp);throw new RuntimeException('Rename failed: '.$file);}
}
if($command==='--help'){said('Usage: php '.basename(__FILE__).' --dry-run | --apply | --rollback');exit(0);}
if($command==='--rollback'){
 if(!is_file($stateFile))failPatch('No installer backup found.');
 $state=json_decode(file_get_contents($stateFile),true,512,JSON_THROW_ON_ERROR);$conflicts=[];
 foreach($state['entries'] as $name=>$entry)if(hashNow($root.'/'.$name)!==$entry['installed'])$conflicts[]=$name;
 if($conflicts)failPatch("Files changed after install; rollback stopped:\n - ".implode("\n - ",$conflicts));
 foreach($state['entries'] as $name=>$entry){
  $file=$root.'/'.$name;
  if($entry['previous']===null){if(is_file($file))unlink($file);}
  else storePatch($file,file_get_contents($backupDir.'/files/'.$name));
  said('RESTORED '.$name);
 }
 @unlink($stateFile);said('File rollback complete. Seeded database data, stock/journals and copied public images are NOT removed.');exit(0);
}
if(is_file($stateFile))failPatch('Patch already installed; use --rollback to undo source-file changes.');
$encoded=trim(substr(file_get_contents(__FILE__),__COMPILER_HALT_OFFSET__));
$binary=base64_decode($encoded,true);if($binary===false)failPatch('Invalid installer payload.');
$source=gzuncompress($binary);if($source===false)failPatch('Cannot decompress installer payload.');
$payload=json_decode($source,true,512,JSON_THROW_ON_ERROR);$changed=[];$current=[];$conflicts=[];
foreach($payload['entries'] as $name=>$entry){
 if(!preg_match('~^(database/seeders/|routes/|NEXABIZ_ECOMMERCE_DEMO_SEEDER_README\.md$)~',$name)||str_contains($name,'..')||str_contains($name,'\\'))failPatch('Unsafe file path: '.$name);
 $hash=hashNow($root.'/'.$name);
 if($hash===$entry['new']){$current[]=$name;continue;}
 if($hash!==$entry['old']){$conflicts[]=$name;continue;}
 $changed[$name]=$entry;
}
said('NexaBiz ecommerce demo data: '.count($changed).' file changes; '.count($current).' unchanged; '.count($conflicts).' conflicts.');
if($conflicts){foreach($conflicts as $name)said('CONFLICT '.$name);failPatch('No files changed. Review customized files or ensure previous patches were applied.');}
if($command==='--dry-run'){foreach($changed as $name=>$entry)said(($entry['old']===null?'ADD ':'UPDATE ').$name);exit(0);}
if(!$changed){said('Files already current.');exit(0);}
$restore=[];
foreach($changed as $name=>$entry){
 $restore[$name]=['previous'=>$entry['old'],'installed'=>$entry['new']];
 if($entry['old']!==null){$backup=$backupDir.'/files/'.$name;$dir=dirname($backup);
  if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))failPatch('Cannot create backup directory.');
  if(!copy($root.'/'.$name,$backup))failPatch('Cannot back up '.$name);
 }
}
try{
 foreach($changed as $name=>$entry){
  $data=base64_decode($entry['data'],true);
  if($data===false||hash('sha256',$data)!==$entry['new'])throw new RuntimeException('Bad payload hash for '.$name);
  storePatch($root.'/'.$name,$data);said('OK '.$name);
 }
 storePatch($stateFile,json_encode(['version'=>$payload['version'],'entries'=>$restore],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
 said('Installed source files and images. Next: composer dump-autoload; php artisan ecommerce:demo-businesses; php artisan ecommerce:seed-demo BUSINESS_ID');
}catch(Throwable $e){
 fwrite(STDERR,'Installation failed: '.$e->getMessage()."\nRestoring...\n");
 foreach($restore as $name=>$entry){$target=$root.'/'.$name;
  if($entry['previous']===null){if(is_file($target))@unlink($target);}
  elseif(is_file($backupDir.'/files/'.$name))storePatch($target,file_get_contents($backupDir.'/files/'.$name));
 }exit(1);
}
__halt_compiler();

